"use client";
/* eslint-disable react-hooks/purity, react-hooks/set-state-in-effect, react-hooks/exhaustive-deps */

import { useEffect, useMemo, useRef, useState } from "react";
import type { Content, Exercise, LearnerState, Lesson, Preposition, Reading, Skill, Vocab } from "./portal-types";
import { officialResources, plannedMinutes, studyPlanDays, studyPlanWeeks, type StudyPlanDay } from "./study-plan";

type View = "home" | "practice" | "lessons" | "roadmap" | "labs" | "analytics";
type Mode = "daily" | "weak" | Skill;
type TutorFeedback = { score?:number; summary?:string; corrections?:string[]; betterItalian?:string; nextStep?:string; evaluator?:"ai"|"rubric" };
type SaveLearner = (update:(current:LearnerState)=>LearnerState)=>void;
const skills: Skill[] = ["grammar","vocabulary","reading","listening","writing","speaking","interaction"];
const blank: LearnerState = { xp:0, attempts:0, correct:0, studyDays:[], dailyGoal:40, revision:0, planStart:"", planDays:{}, cefrEvidence:{}, cards:{}, mastery:{}, exerciseStats:{}, activity:[] };

const nav: {id:View;it:string;en:string}[] = [
  {id:"home",it:"Oggi",en:"Today"},{id:"roadmap",it:"Piano 56",en:"56-day plan"},{id:"lessons",it:"Lezioni",en:"Lessons"},{id:"practice",it:"Allenamento",en:"Practice"},{id:"labs",it:"Laboratori",en:"Labs"},{id:"analytics",it:"Progressi",en:"Progress"},
];

const tourSteps: {view:View;anchor:string;kicker:string;titleIt:string;titleEn:string;bodyIt:string;bodyEn:string}[] = [
  {view:"home",anchor:"today",kicker:"01 · OGGI / TODAY",titleIt:"Comincia sempre da qui.",titleEn:"Always start here.",bodyIt:"La pagina Oggi trova il primo giorno incompleto e trasforma il piano in quattro blocchi chiari. Spunta solo ciò che hai davvero fatto.",bodyEn:"Today finds your first unfinished day and turns it into four clear blocks. Check off only work you actually completed."},
  {view:"home",anchor:"language",kicker:"02 · LINGUA / LANGUAGE",titleIt:"Scegli quanto inglese vedere.",titleEn:"Choose how much English you see.",bodyIt:"Bilingue mostra il supporto inglese. Immersione lo nasconde per farti inferire dal contesto. Premi T in qualsiasi momento.",bodyEn:"Bilingual shows English support. Immersion hides it so you infer from context. Press T at any time."},
  {view:"roadmap",anchor:"plan",kicker:"03 · PIANO / PLAN",titleIt:"Il libro resta nell’ordine giusto.",titleEn:"The book stays in the right order.",bodyIt:"Apri un giorno, segui le pagine indicate, registra minuti e sicurezza, poi lascia una nota sull’errore da riprendere.",bodyEn:"Open a day, follow its page references, log time and confidence, then note the error you need to revisit."},
  {view:"practice",anchor:"practice",kicker:"04 · ALLENAMENTO / PRACTICE",titleIt:"Misura con una prova, non con una sensazione.",titleEn:"Measure with evidence, not a feeling.",bodyIt:"Scegli il mix quotidiano o un’abilità. Le risposte aggiornano la padronanza; il feedback lungo usa sempre la rubrica locale gratuita.",bodyEn:"Choose the daily mix or one skill. Answers update mastery; extended feedback always has a free local-rubric mode."},
  {view:"labs",anchor:"labs",kicker:"05 · LABORATORI / LABS",titleIt:"Ripassa in quattro modi diversi.",titleEn:"Review in four different ways.",bodyIt:"Carte, letture, preposizioni e giochi servono il piano. Le carte tornano quando sono dovute, non in un flusso infinito.",bodyEn:"Cards, readings, prepositions and games support the plan. Cards return when due instead of becoming an endless feed."},
  {view:"analytics",anchor:"progress",kicker:"06 · PROGRESSI / PROGRESS",titleIt:"Raccogli prove reali del tuo A1.",titleEn:"Collect real evidence of your A1.",bodyIt:"Pagine, minuti, test e cinque abilità CEFR restano separati. Aggiungi registrazioni o scritti datati: nessun singolo numero finge di essere il tuo livello.",bodyEn:"Pages, minutes, tests and five CEFR skills stay separate. Add dated recordings or writing samples; no single number pretends to be your level."},
];

const normalise = (value:string) => value.toLocaleLowerCase("it").normalize("NFKD").replace(/[\u0300-\u036f]/g,"").replace(/[.,!?;:“”’'()]/g,"").replace(/\s+/g," ").trim();
const bi = (translated:boolean,it:string,en:string) => translated?`${it} · ${en}`:it;
const accuracy = (attempts=0, correct=0) => attempts ? Math.round(correct/attempts*100) : 0;
const masteryFor = (state:LearnerState, lessonId:string, skill:Skill) => state.mastery[`${lessonId}:${skill}`] || {attempts:0,correct:0,xp:0,lastSeen:""};
const lessonScore = (state:LearnerState, lessonId:string) => {const measured=skills.map(skill=>masteryFor(state,lessonId,skill)).filter(item=>item.attempts>0);return{score:measured.length?Math.round(measured.reduce((sum,item)=>sum+accuracy(item.attempts,item.correct),0)/measured.length):null,coverage:measured.length}};
const localDateKey = (date=new Date()) => {
  const parts=new Intl.DateTimeFormat("en-GB",{timeZone:"Europe/London",year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(date),part=(type:string)=>parts.find(value=>value.type===type)?.value||"";
  return `${part("year")}-${part("month")}-${part("day")}`;
};
const storageGet = (key:string) => {try{return window.localStorage.getItem(key)}catch{return null}};
const storageSet = (key:string,value:string) => {try{window.localStorage.setItem(key,value)}catch{}};
const storageRemove = (key:string) => {try{window.localStorage.removeItem(key)}catch{}};
const planDate = (start:string, day:number) => {const date=new Date(`${start || localDateKey()}T12:00:00`);date.setDate(date.getDate()+day-1);return date};
const dayProgress = (state:LearnerState, day:number) => state.planDays[String(day)] || {completedTaskIds:[],actualMinutes:0,confidence:0,note:""};
const areTasksComplete = (state:LearnerState, day:StudyPlanDay) => day.tasks.every(task=>dayProgress(state,day.day).completedTaskIds.includes(task.id));
const isDayComplete = (state:LearnerState, day:StudyPlanDay) => areTasksComplete(state,day)&&(!day.scored||dayProgress(state,day.day).testScore!==undefined);

function expandExercises(content:Content): Exercise[] {
  const generated = content.lesson.flatMap((lesson):Exercise[] => [
    {id:`${lesson.id}-it`,lessonId:lesson.id,skill:"writing",type:"input",prompt:`Translate into Italian: ${lesson.english}`,answer:lesson.italian,explanation:`Model: ${lesson.italian}`},
    {id:`${lesson.id}-en`,lessonId:lesson.id,skill:"reading",type:"input",prompt:`Translate into English: ${lesson.italian}`,answer:lesson.english,explanation:`Meaning: ${lesson.english}`},
    {id:`${lesson.id}-listen`,lessonId:lesson.id,skill:"listening",type:"listen",prompt:"Listen and type the Italian sentence.",answer:lesson.italian,audioText:lesson.italian,explanation:`${lesson.italian} — ${lesson.english}`},
    {id:`${lesson.id}-recall`,lessonId:lesson.id,skill:"grammar",type:"input",prompt:lesson.prompt,answer:lesson.answer,explanation:`Answer: ${lesson.answer}`},
    {id:`${lesson.id}-speak`,lessonId:lesson.id,skill:"speaking",type:"speak",prompt:`Can-do challenge: ${lesson.canDo}`,answer:lesson.italian,hint:`Use this model if useful: ${lesson.italian}`,explanation:"Aim for clear communication, two or more connected sentences, and accurate core verbs."},
  ]);
  const correctionExercises = content.lesson.flatMap((lesson):Exercise[] => lesson.mistakes.map((mistake,index)=>({
    id:`${lesson.id}-correction-${index}`,lessonId:lesson.id,skill:"grammar",type:"mcq",
    prompt:`Correggi la frase: “${mistake.wrong}”`,answer:mistake.right,
    options:index%2?[mistake.wrong,mistake.right]:[mistake.right,mistake.wrong],
    explanation:`${mistake.right} — ${mistake.noteIt}`
  })));
  const vocabExercises = content.vocab.flatMap((word):Exercise[] => [
    {id:`${word.id}-prod`,lessonId:"vocab",skill:"vocabulary",type:"input",prompt:`Write the Italian for: ${word.english}`,answer:word.italian,explanation:word.example},
    {id:`${word.id}-rec`,lessonId:"vocab",skill:"vocabulary",type:"input",prompt:`What does “${word.italian}” mean?`,answer:word.english,explanation:word.example},
  ]);
  return [...content.exercise,...generated,...correctionExercises,...vocabExercises];
}

export default function Home() {
  const [content,setContent]=useState<Content|null>(null);
  const [learner,setLearner]=useState<LearnerState>(blank);
  const [view,setView]=useState<View>("home");
  const [translated,setTranslated]=useState(true);
  const [translationToast,setTranslationToast]=useState(false);
  const [tourOpen,setTourOpen]=useState(false);
  const [selected,setSelected]=useState<Lesson|null>(null);
  const [practiceLesson,setPracticeLesson]=useState<string>("");
  const [status,setStatus]=useState("Collegamento al database…");
  const tourButtonRef=useRef<HTMLButtonElement>(null);
  const learnerRef=useRef<LearnerState>(blank);
  const serverRevisionRef=useRef(0);
  const persistQueue=useRef<Promise<void>>(Promise.resolve());

  const enqueuePersist=(snapshot:LearnerState,successMessage="Progressi salvati",rebase?:(current:LearnerState)=>LearnerState)=>{
    persistQueue.current=persistQueue.current.catch(()=>undefined).then(async()=>{
      const send=async(state:LearnerState,expected:number)=>{const response=await fetch("/api/progress",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({state,revision:expected})});const data=await response.json().catch(()=>({}));return{response,data}};
      let state=snapshot,expected=serverRevisionRef.current,{response,data}=await send(state,expected);
      if(response.status===409){const serverRevision=Math.max(0,Number(data.revision||0)),serverState=data.state as LearnerState|null;serverRevisionRef.current=serverRevision;if(serverRevision<expected){state={...snapshot,revision:serverRevision+1}}else if(rebase&&serverState){state={...rebase({...blank,...serverState,revision:serverRevision}),revision:serverRevision+1}}else throw new Error("revision_conflict");expected=serverRevision;({response,data}=await send(state,expected))}
      if(!response.ok)throw new Error(data.error||"save_failed");
      const confirmedRevision=Math.max(0,Number(data.revision||state.revision));
      serverRevisionRef.current=confirmedRevision;
      if(learnerRef.current.revision===snapshot.revision){const confirmed={...learnerRef.current,revision:confirmedRevision};learnerRef.current=confirmed;setLearner(confirmed);storageSet("parliamo-offline-cache",JSON.stringify(confirmed));storageRemove("parliamo-offline-dirty");setStatus(successMessage)}
    }).catch(()=>setStatus("Salvato nel browser · nuovo tentativo al prossimo avvio"));
  };

  useEffect(()=>{
    const savedMode=storageGet("parliamo-translation-mode");
    if(savedMode) setTranslated(savedMode==="bilingual");
    Promise.all([fetch("/api/content").then(r=>r.ok?r.json():Promise.reject()),fetch("/api/progress").then(r=>r.ok?r.json():null)])
      .then(([catalog,progress])=>{
        setContent(catalog.content as Content);
        const cached=storageGet("parliamo-offline-cache");
        let cachedState:LearnerState|null=null;
        try{cachedState=cached?JSON.parse(cached) as LearnerState:null}catch{storageRemove("parliamo-offline-cache")}
        const remoteState=progress?.state as LearnerState|undefined,remoteRevision=Math.max(0,Number(progress?.revision??remoteState?.revision??0));
        serverRevisionRef.current=remoteRevision;
        const cacheDirty=storageGet("parliamo-offline-dirty")==="true",useCache=Boolean(cachedState&&((cachedState.revision||0)>remoteRevision||(cacheDirty&&(cachedState.revision||0)>=remoteRevision)));
        const source=(useCache?cachedState:remoteState)||cachedState||blank;
        const next={...blank,...source,revision:useCache?remoteRevision+1:remoteRevision,planStart:source.planStart||localDateKey(),planDays:source.planDays||{},cefrEvidence:source.cefrEvidence||{},cards:source.cards||{},mastery:source.mastery||{},exerciseStats:source.exerciseStats||{},activity:source.activity||[],studyDays:source.studyDays||[]};
        learnerRef.current=next;setLearner(next);storageSet("parliamo-offline-cache",JSON.stringify(next));
        if(useCache){setStatus("Recupero del salvataggio locale…");enqueuePersist(next,"Cache locale recuperata e sincronizzata",()=>next)}
        else setStatus(remoteState?"Progressi locali sincronizzati":"Percorso pronto · nuovo inizio");
      }).catch(()=>setStatus("Database non disponibile · avvia con Start Parliamo.command"));
  },[]);

  useEffect(()=>{
    if(!content||storageGet("parliamo-guided-tour-v1")==="seen")return;
    const timer=window.setTimeout(()=>setTourOpen(true),700);
    return()=>window.clearTimeout(timer);
  },[content]);

  const toggleTranslations=()=>{
    const next=!translated;
    setTranslated(next);
    setTranslationToast(true);
    storageSet("parliamo-translation-mode",next?"bilingual":"immersion");
    window.setTimeout(()=>setTranslationToast(false),2200);
  };
  useEffect(()=>{const key=(event:KeyboardEvent)=>{const target=event.target as HTMLElement;if(event.key.toLowerCase()==="t"&&!target.matches("input, textarea, select")&&!target.isContentEditable)toggleTranslations()};window.addEventListener("keydown",key);return()=>window.removeEventListener("keydown",key)},[translated]);
  useEffect(()=>{const root=document.documentElement,previous=root.style.scrollBehavior;root.style.scrollBehavior="auto";root.scrollTop=0;document.body.scrollTop=0;window.scrollTo(0,0);const frame=window.requestAnimationFrame(()=>{root.scrollTop=0;document.body.scrollTop=0;root.style.scrollBehavior=previous});return()=>window.cancelAnimationFrame(frame)},[view]);

  const save:SaveLearner=(update)=>{
    const current=learnerRef.current,next=update(current),updated={...next,revision:(current.revision||0)+1};
    learnerRef.current=updated;setLearner(updated);storageSet("parliamo-offline-cache",JSON.stringify(updated));storageSet("parliamo-offline-dirty","true");setStatus("Salvataggio locale…");
    enqueuePersist(updated,"Progressi salvati",update);
  };
  const record=(exercise:Exercise,correct:boolean,responseMs:number,xp:number)=>{
    const now=new Date().toISOString(), today=localDateKey(), key=`${exercise.lessonId}:${exercise.skill}`;
    save(current=>{const m=masteryFor(current,exercise.lessonId,exercise.skill),e=current.exerciseStats[exercise.id]||{attempts:0,correct:0,lastSeen:"",bestMs:0};return{...current,xp:current.xp+xp,attempts:current.attempts+1,correct:current.correct+(correct?1:0),studyDays:current.studyDays.includes(today)?current.studyDays:[...current.studyDays,today],mastery:{...current.mastery,[key]:{attempts:m.attempts+1,correct:m.correct+(correct?1:0),xp:m.xp+xp,lastSeen:now}},exerciseStats:{...current.exerciseStats,[exercise.id]:{attempts:e.attempts+1,correct:e.correct+(correct?1:0),lastSeen:now,bestMs:e.bestMs?Math.min(e.bestMs,responseMs):responseMs}},activity:[...current.activity,{date:now,type:exercise.type,xp,correct,lessonId:exercise.lessonId,skill:exercise.skill}].slice(-1000)}});
    fetch("/api/progress",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({lessonId:exercise.lessonId,skill:exercise.skill,exerciseId:exercise.id,correct,xp,responseMs})}).catch(()=>{});
  };
  const startLesson=(id:string)=>{setSelected(null);setPracticeLesson(id);setView("practice")};
  const closeTour=()=>{storageSet("parliamo-guided-tour-v1","seen");setTourOpen(false);window.setTimeout(()=>tourButtonRef.current?.focus(),0)};

  if(!content) return <main className="loading"><span className="brand-mark">P</span><h1>Prepariamo il tuo italiano…</h1><p>{status}</p></main>;
  const exercises=expandExercises(content);
  return <div className="app-shell">
    <a className="skip-link" href="#main-content">Vai al contenuto</a>
    <header className="topbar"><button className="brand" onClick={()=>setView("home")}><span className="brand-mark">P</span><span><strong>Parliamo!</strong><small>Italiano A1 · 8 settimane {translated&&"· 8 weeks"}</small></span></button><nav aria-label="Navigazione principale">{nav.map(n=><button key={n.id} className={view===n.id?"active":""} aria-current={view===n.id?"page":undefined} onClick={()=>setView(n.id)}><span>{n.it}</span>{translated&&<small>{n.en}</small>}</button>)}</nav><div className="topbar-tools"><button ref={tourButtonRef} className="tour-launch" data-tour="guide" onClick={()=>setTourOpen(true)} aria-label="Apri la guida del sito"><b>?</b><span>Guida{translated&&<small>Guide</small>}</span></button><TranslationControl bilingual={translated} toggle={toggleTranslations}/></div></header>
    {translationToast&&<div className={`translation-toast ${translated?"bilingual":"immersion"}`} role="status"><span>{translated?"EN":"IT"}</span><div><strong>{translated?"Modalità bilingue attiva":"Modalità immersione attiva"}</strong><small>{translated?"Le traduzioni inglesi sono visibili come supporto.":"L’inglese è nascosto: prova a capire dal contesto."}</small></div></div>}
    <main id="main-content" tabIndex={-1}>
      {view==="home"&&<Dashboard content={content} learner={learner} save={save} go={setView} open={setSelected} status={status} translated={translated}/>}
      {view==="practice"&&<PracticeLab content={content} exercises={exercises} learner={learner} lessonId={practiceLesson} clearLesson={()=>setPracticeLesson("")} record={record} translated={translated}/>} 
      {view==="lessons"&&<Lessons content={content} learner={learner} open={setSelected} start={startLesson} translated={translated}/>} 
      {view==="roadmap"&&<Roadmap content={content} learner={learner} save={save} start={startLesson} translated={translated}/>}
      {view==="labs"&&<LabsHub content={content} learner={learner} save={save} record={record} translated={translated}/>}
      {view==="analytics"&&<Analytics content={content} learner={learner} save={save} translated={translated}/>}
    </main>
    <footer><span>Parliamo! · Il tuo sprint A1 in 56 giorni {translated&&"· Your 56-day A1 sprint"}</span><span>{exercises.length} esercizi attivi {translated&&"· active exercises"} · {status}</span></footer>
    {selected&&<LessonPanel lesson={selected} content={content} learner={learner} translated={translated} close={()=>setSelected(null)} start={startLesson}/>}
    <GuidedTour open={tourOpen} translated={translated} go={setView} close={closeTour}/>
  </div>;
}

function TranslationControl({bilingual,toggle}:{bilingual:boolean;toggle:()=>void}){
  return <button className={`language-mode ${bilingual?"bilingual":"immersion"}`} data-tour="language" onClick={toggle} aria-pressed={bilingual} aria-label={bilingual?"Switch to Italian immersion mode":"Show Italian with English translations"} title={bilingual?"Hide English translations":"Show English translations"}>
    <span className="language-mode-label"><small>LINGUA · LANGUAGE · T</small><strong>{bilingual?"Bilingue · Bilingual":"Immersione · Immersion"}</strong></span>
    <span className="language-track" aria-hidden="true"><i/><b>IT</b><b>IT+EN</b></span>
  </button>;
}

function CopyButton({text}:{text:string}){const [done,setDone]=useState(false);const copy=async()=>{await navigator.clipboard.writeText(text);setDone(true);window.setTimeout(()=>setDone(false),1400)};return <button className={`copy-phrase ${done?"done":""}`} onClick={copy}>{done?"✓ Copiata":"⧉ Copia frase"}</button>}

function GuidedTour({open,translated,go,close}:{open:boolean;translated:boolean;go:(view:View)=>void;close:()=>void}){
  const [index,setIndex]=useState(0),[rect,setRect]=useState<{top:number;left:number;width:number;height:number}|null>(null),cardRef=useRef<HTMLDivElement>(null),step=tourSteps[index];
  useEffect(()=>{if(open)setIndex(0)},[open]);
  useEffect(()=>{
    if(!open)return;
    const background=[...document.querySelectorAll<HTMLElement>(".app-shell > header, .app-shell > main, .app-shell > footer")];
    background.forEach(element=>{element.inert=true;element.setAttribute("aria-hidden","true")});
    return()=>background.forEach(element=>{element.inert=false;element.removeAttribute("aria-hidden")});
  },[open]);
  useEffect(()=>{
    if(!open)return;
    go(step.view);
    let timer=0,frame=0;
    const measure=()=>{const target=document.querySelector(`[data-tour="${step.anchor}"]`) as HTMLElement|null;if(!target){setRect(null);return}const box=target.getBoundingClientRect(),pad=8,left=Math.max(8,box.left-pad),top=Math.max(8,box.top-pad),right=Math.min(window.innerWidth-8,box.right+pad),bottom=Math.min(window.innerHeight-8,box.bottom+pad);setRect({top,left,width:Math.max(0,right-left),height:Math.max(0,bottom-top)})};
    const scheduleMeasure=()=>{window.cancelAnimationFrame(frame);frame=window.requestAnimationFrame(measure)};
    window.requestAnimationFrame(()=>cardRef.current?.focus());
    timer=window.setTimeout(()=>{const target=document.querySelector(`[data-tour="${step.anchor}"]`) as HTMLElement|null;if(!target){measure();return}const reduced=window.matchMedia("(prefers-reduced-motion: reduce)").matches;target.scrollIntoView({behavior:reduced?"auto":"smooth",block:"center",inline:"center"});scheduleMeasure()},100);
    window.addEventListener("resize",scheduleMeasure);window.addEventListener("scroll",scheduleMeasure,{passive:true});
    return()=>{window.clearTimeout(timer);window.cancelAnimationFrame(frame);window.removeEventListener("resize",scheduleMeasure);window.removeEventListener("scroll",scheduleMeasure)};
  },[open,index,step,go]);
  useEffect(()=>{if(!open)return;const key=(event:KeyboardEvent)=>{if(event.key==="Escape")close();if(event.key==="ArrowRight")setIndex(value=>Math.min(tourSteps.length-1,value+1));if(event.key==="ArrowLeft")setIndex(value=>Math.max(0,value-1));if(event.key==="Tab"&&cardRef.current){const controls=[...cardRef.current.querySelectorAll<HTMLElement>("button")].filter(item=>!item.hasAttribute("disabled"));if(!controls.length)return;const first=controls[0],last=controls.at(-1)!;if(event.shiftKey&&(document.activeElement===first||document.activeElement===cardRef.current)){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}else if(!cardRef.current.contains(document.activeElement)){event.preventDefault();first.focus()}}};document.addEventListener("keydown",key);return()=>document.removeEventListener("keydown",key)},[open,close]);
  if(!open)return null;
  const final=index===tourSteps.length-1;
  return <div className="guided-tour" role="presentation">{rect&&<div className="tour-spotlight" aria-hidden="true" style={rect}/>}<div className="tour-card" ref={cardRef} role="dialog" aria-modal="true" aria-labelledby="tour-title" aria-describedby={translated?"tour-body tour-body-en":"tour-body"} tabIndex={-1}><div className="tour-card-head"><span>{step.kicker}</span><button onClick={close} aria-label="Chiudi la guida · Close guide">×</button></div><div className="tour-dots" aria-label={`Passaggio ${index+1} di ${tourSteps.length}`}>{tourSteps.map((_,dot)=><i key={dot} className={dot===index?"active":dot<index?"done":""}/>)}</div><h2 id="tour-title">{step.titleIt}</h2>{translated&&<h3 className="translation-reveal" lang="en">{step.titleEn}</h3>}<p id="tour-body">{step.bodyIt}</p>{translated&&<p id="tour-body-en" className="tour-english translation-reveal" lang="en">{step.bodyEn}</p>}<div className="tour-actions"><button className="tour-skip" onClick={close}>Salta {translated&&"· Skip"}</button><div>{index>0&&<button className="secondary" onClick={()=>setIndex(index-1)}>← Indietro {translated&&"· Back"}</button>}<button className="primary" onClick={()=>{if(final){go("home");close()}else setIndex(index+1)}}>{final?`Inizia ${translated?"· Start":""}`:`Avanti ${translated?"· Next":""}`} →</button></div></div><small className="tour-keyboard">← → per navigare · Esc per chiudere {translated&&"· Arrow keys to navigate · Esc to close"}</small></div></div>;
}

function Dashboard({content,learner,save,go,open,status,translated}:{content:Content;learner:LearnerState;save:SaveLearner;go:(v:View)=>void;open:(l:Lesson)=>void;status:string;translated:boolean}){
  const totalTasks=studyPlanDays.reduce((sum,day)=>sum+day.tasks.length,0), completedTasks=studyPlanDays.reduce((sum,day)=>sum+dayProgress(learner,day.day).completedTaskIds.filter(id=>day.tasks.some(task=>task.id===id)).length,0);
  const completedDays=studyPlanDays.filter(day=>isDayComplete(learner,day)).length, current=studyPlanDays.find(day=>!isDayComplete(learner,day))||studyPlanDays.at(-1)!;
  const progress=dayProgress(learner,current.day), planned=current.tasks.reduce((sum,task)=>sum+task.minutes,0), actualMinutes=Object.values(learner.planDays).reduce((sum,day)=>sum+(day.actualMinutes||0),0);
  const currentLesson=content.lesson.find(lesson=>lesson.id===current.lessonId), currentScore=currentLesson?lessonScore(learner,currentLesson.id):null;
  const finish=planDate(learner.planStart,56), percent=Math.round(completedTasks/totalTasks*100);
  const toggle=(taskId:string)=>{const today=localDateKey();save(state=>{const latest=dayProgress(state,current.day),completed=latest.completedTaskIds.includes(taskId),ids=completed?latest.completedTaskIds.filter(id=>id!==taskId):[...latest.completedTaskIds,taskId];return{...state,studyDays:completed||state.studyDays.includes(today)?state.studyDays:[...state.studyDays,today],planDays:{...state.planDays,[String(current.day)]:{...latest,completedTaskIds:ids,completedAt:ids.length===current.tasks.length?new Date().toISOString():undefined}}}})};
  return <>
    <section className="hero sprint-hero page-width" data-tour="today"><div className="hero-copy"><p className="eyebrow">GIORNO {current.day} DI 56 · NUOVO ESPRESSO 1 · ED. 2014</p><h1>Otto settimane.<br/><em>Italiano che resta.</em></h1><p className="hero-sub">Un percorso di consolidamento costruito sul tuo libro, 28 lezioni Imperial e prove reali in ascolto, lettura, interazione, parlato e scrittura.</p>{translated&&<p className="translation-line translation-reveal" lang="en">An intensive consolidation programme based on your textbook, 28 Imperial course lessons, and real-world evidence across five CEFR skill areas.</p>}<div className="hero-actions"><button className="primary" onClick={()=>go("roadmap")}>{bi(translated,`Apri il giorno ${current.day}`,`Open day ${current.day}`)} →</button><button className="secondary" onClick={()=>go("practice")}>{bi(translated,"Allenamento adattivo","Adaptive practice")}</button></div><small className="sync-status" role="status" aria-live="polite">● {status} · {bi(translated,"fine prevista","expected finish")} {finish.toLocaleDateString("it-IT",{day:"numeric",month:"long",year:"numeric"})}</small></div><div className="daily-card sprint-card"><div className="daily-ring" style={{"--p":`${percent}%`} as React.CSSProperties}><strong>{percent}%</strong><span>{completedTasks}/{totalTasks} {bi(translated,"attività","tasks")}</span></div><p className="script">{bi(translated,"Oggi si fa","Today’s work")}</p><h3>{current.titleIt}</h3>{translated&&<small className="inline-translation translation-reveal" lang="en">{current.titleEn}</small>}<p>{planned} {bi(translated,"min pianificati","min planned")} · {progress.completedTaskIds.length}/4 {bi(translated,"blocchi","blocks")}</p><span className="edition-pill">{bi(translated,"Edizione precedente · pagine verificate","Original edition · verified pages")}</span></div></section>
    <section className="stats page-width sprint-stats"><div><strong>{completedDays}<small>/56</small></strong><span>giorni completati</span>{translated&&<small className="stat-translation translation-reveal">completed days</small>}</div><div><strong>{Math.round(actualMinutes/60)}h</strong><span>tempo registrato</span>{translated&&<small className="stat-translation translation-reveal">logged time</small>}</div><div><strong>{learner.attempts?`${accuracy(learner.attempts,learner.correct)}%`:"—"}</strong><span>{learner.attempts?"precisione":"ancora da misurare"}</span>{translated&&<small className="stat-translation translation-reveal">{learner.attempts?"practice accuracy":"not yet measured"}</small>}</div><div><strong>{learner.studyDays.length}</strong><span>giorni di studio reali</span>{translated&&<small className="stat-translation translation-reveal">days with real activity</small>}</div></section>
    <section className="today agenda page-width"><div className="section-heading"><div><p className="eyebrow">OGGI · TODAY · {current.source}</p><h2>{current.titleIt}</h2>{translated&&<p className="micro-translation translation-reveal">{current.titleEn}</p>}</div><button onClick={()=>go("roadmap")}>{bi(translated,"Vedi tutto il piano","View the full plan")} →</button></div><div className="agenda-grid">{current.tasks.map((task,index)=>{const done=progress.completedTaskIds.includes(task.id);return <label className={done?"agenda-task done":"agenda-task"} key={task.id}><input type="checkbox" checked={done} onChange={()=>toggle(task.id)}/><span className="agenda-index">0{index+1}</span><span><small>{task.titleIt} · {task.minutes} min</small><strong>{task.detailIt}</strong>{translated&&<em className="translation-reveal">{task.detailEn}</em>}</span></label>})}</div></section>
    <section className="week-strip page-width" aria-label="Otto settimane"><div><div><p className="eyebrow">IL PERCORSO {translated&&"· THE JOURNEY"}</p><h2>Dal libro alla vita reale</h2>{translated&&<p className="micro-translation translation-reveal">From the book to real life</p>}</div></div><div className="week-strip-grid">{studyPlanWeeks.map(week=>{const done=week.days.filter(day=>isDayComplete(learner,day)).length;return <button key={week.week} className={current.week===week.week?"active":""} onClick={()=>go("roadmap")}><span>{String(week.week).padStart(2,"0")}</span><strong>{week.titleIt}</strong>{translated&&<em>{week.titleEn}</em>}<small>{done}/7 {bi(translated,"giorni","days")}</small></button>})}</div></section>
    {currentLesson&&<section className="continue page-width"><div className="continue-copy"><p className="eyebrow">LEZIONE COLLEGATA {translated&&"· LINKED LESSON"}</p><h2>{currentLesson.title}</h2><p>{currentLesson.canDoIt}</p>{translated&&<p className="micro-translation translation-reveal">{currentLesson.canDo}</p>}<div className="tag-row">{currentLesson.topics.map(topic=><span key={topic}>{topic}</span>)}</div><button className="primary" onClick={()=>open(currentLesson)}>{bi(translated,"Apri la scheda della lezione","Open lesson hub")} →</button></div><div className="phrase-card"><span>{bi(translated,"PADRONANZA MISURATA","MEASURED MASTERY")}</span><blockquote>{currentScore?.score===null?bi(translated,"Non ancora misurata","Not yet measured"):`${currentScore?.score}%`}</blockquote><p>{currentScore?.coverage||0} {bi(translated,"di 7 abilità con prove","of 7 skills evidenced")}</p>{translated&&<small className="translation-reveal">Unattempted skills stay unmeasured rather than being scored as weak.</small>}</div></section>}
  </>;
}

function PracticeLab({content,exercises,learner,lessonId,clearLesson,record,translated}:{content:Content;exercises:Exercise[];learner:LearnerState;lessonId:string;clearLesson:()=>void;record:(e:Exercise,c:boolean,ms:number,xp:number)=>void;translated:boolean}){
  const [mode,setMode]=useState<Mode>("daily"),[length,setLength]=useState(10),[seed,setSeed]=useState(0),[index,setIndex]=useState(0),[session,setSession]=useState<Exercise[]>([]),[ready,setReady]=useState(false),[answer,setAnswer]=useState(""),[built,setBuilt]=useState<string[]>([]),[result,setResult]=useState<null|boolean>(null),[score,setScore]=useState(0),[started,setStarted]=useState(Date.now()),[feedback,setFeedback]=useState<TutorFeedback|null>(null),[waiting,setWaiting]=useState(false);
  const submitted=useRef(false);
  useEffect(()=>{
    let pool=lessonId?exercises.filter(e=>e.lessonId===lessonId):exercises;
    if(mode!=="daily"&&mode!=="weak") pool=pool.filter(e=>e.skill===mode);
    if(mode==="weak") pool=[...pool].sort((a,b)=>accuracy(learner.exerciseStats[a.id]?.attempts,learner.exerciseStats[a.id]?.correct)-accuracy(learner.exerciseStats[b.id]?.attempts,learner.exerciseStats[b.id]?.correct));
    else pool=[...pool].sort(()=>Math.random()-.5);
    const balanced:Exercise[]=[]; skills.forEach(skill=>{const found=pool.find(e=>e.skill===skill);if(found)balanced.push(found)}); pool.forEach(e=>{if(!balanced.includes(e))balanced.push(e)});
    setSession(balanced.slice(0,length));setIndex(0);setAnswer("");setBuilt([]);setResult(null);setScore(0);setStarted(Date.now());setFeedback(null);submitted.current=false;setReady(true);
  },[mode,length,seed,lessonId]);
  if(!ready)return <section className="practice-shell page-width page-top" data-tour="practice"><p className="eyebrow">{bi(translated,"PREPARIAMO LA SESSIONE","PREPARING YOUR SESSION")}</p><h1>{bi(translated,"Un momento…","One moment…")}</h1></section>;
  if(!session.length)return <section className="practice-shell page-width page-top" data-tour="practice"><h1>{bi(translated,"Nessun esercizio in questa selezione.","There are no exercises in this selection.")}</h1><button className="secondary" onClick={()=>setMode("daily")}>{bi(translated,"Torna al mix quotidiano","Return to the daily mix")}</button></section>;
  const finish=index>=session.length;
  if(finish)return <section className="quiz-finish page-width page-top" data-tour="practice"><div className="score-ring"><strong>{score}</strong><span>/ {session.length}</span></div><p className="eyebrow">{bi(translated,"SESSIONE COMPLETATA","SESSION COMPLETE")}</p><h1>{score/session.length>=.8?bi(translated,"Ottimo lavoro.","Great work."):bi(translated,"Gli errori stanno già preparando il prossimo ripasso.","Your mistakes are already shaping the next review.")}</h1><p>{bi(translated,"La mappa locale ha aggiornato ogni abilità, lezione e tempo di risposta.","Your local tracker has updated every skill, lesson and response time.")}</p><button className="primary" onClick={()=>setSeed(seed+1)}>{bi(translated,"Nuova sessione adattiva","New adaptive session")} →</button></section>;
  const item=session[index];
  const response=item.type==="reorder"?built.join(" "):answer;
  const submit=()=>{if(submitted.current||!response.trim())return;submitted.current=true;const ok=[item.answer,...(item.alternatives||[])].some(a=>normalise(a)===normalise(response));setResult(ok);if(ok)setScore(score+1);record(item,ok,Date.now()-started,ok?8:2)};
  const selfGrade=(ok:boolean)=>{if(submitted.current)return;submitted.current=true;setResult(ok);if(ok)setScore(score+1);record(item,ok,Date.now()-started,ok?10:3)};
  const next=()=>{submitted.current=false;setIndex(index+1);setAnswer("");setBuilt([]);setResult(null);setFeedback(null);setStarted(Date.now())};
  const listen=()=>{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(item.audioText||item.answer);u.lang="it-IT";u.rate=.72;speechSynthesis.speak(u)};
  const taskHelp={mcq:"Choose the most natural and grammatically correct option.",input:"Write the complete answer; capitalisation and punctuation do not affect scoring.",reorder:"Tap the tiles in the correct order to build the sentence.",listen:"Listen more than once and transcribe the Italian sentence exactly.",reading:"Read the passage, find the essential information and choose the answer.",speak:"Produce at least two connected sentences, then listen back and assess clarity."}[item.type];
  const evaluate=async()=>{setWaiting(true);try{const r=await fetch("/api/evaluate",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({lessonId:item.lessonId,exerciseId:item.id,skill:item.skill,prompt:item.prompt,response:answer,target:item.answer,hint:item.hint})});const data=await r.json();setFeedback(data.feedback||{summary:data.error})}catch{setFeedback({summary:bi(translated,"La correzione locale non è disponibile in questo momento.","Local review is temporarily unavailable.")})}finally{setWaiting(false)}};
  return <section className="practice-shell page-width page-top" data-tour="practice">
    <div className="practice-head"><div><p className="eyebrow">PALESTRA ADATTIVA · ADAPTIVE PRACTICE · {exercises.length} VARIAZIONI</p><h1>{lessonId?`${bi(translated,"Test della lezione","Lesson check")}: ${content.lesson.find(l=>l.id===lessonId)?.title}`:bi(translated,"Allenamento completo A1","Complete A1 practice")}</h1><p>Ogni risposta aggiorna la tua mappa di lezioni e abilità.</p>{translated&&<p className="translation-line translation-reveal">Every answer updates your lesson and skill mastery map.</p>}<div className="local-review-note"><span>LOCALE · LOCAL</span><p>{bi(translated,"La correzione estesa usa la rubrica inclusa: nessuna chiave API o costo a consumo.","Extended review uses the included rubric: no API key or usage charge.")}</p></div></div>{lessonId&&<button className="secondary" onClick={clearLesson}>{bi(translated,"Tutte le lezioni","All lessons")}</button>}</div>
    <div className="practice-controls"><div>{(["daily","weak",...skills] as Mode[]).map(m=><button key={m} className={mode===m?"active":""} onClick={()=>setMode(m)}>{m==="daily"?bi(translated,"Mix quotidiano","Daily mix"):m==="weak"?bi(translated,"Punti deboli","Weak areas"):bi(translated,content.skill.find(s=>s.id===m)?.it||m,content.skill.find(s=>s.id===m)?.en||m)}</button>)}</div><label>{bi(translated,"Sessione","Session")} <select value={length} onChange={e=>setLength(Number(e.target.value))}><option value="10">10 {bi(translated,"domande","questions")}</option><option value="20">20 {bi(translated,"domande","questions")}</option><option value="30">30 {bi(translated,"domande","questions")}</option></select></label></div>
    <div className="session-progress"><span>{index+1}/{session.length}</span><div><i style={{width:`${index/session.length*100}%`}}/></div><strong>{score} {bi(translated,"corrette","correct")}</strong></div>
    <article className="exercise-card"><div className="exercise-meta"><span>{content.skill.find(s=>s.id===item.skill)?.it||item.skill}{translated&&` · ${content.skill.find(s=>s.id===item.skill)?.en||item.skill}`}</span><span>{content.lesson.find(l=>l.id===item.lessonId)?.title||"Vocabolario A1"}</span><span>{item.type}</span></div>{item.passage&&<blockquote className="passage">{item.passage}</blockquote>}<p className="task-label">CONSEGNA {translated&&"· TASK"}</p><h2 id={`practice-prompt-${item.id}`}>{item.prompt}</h2>{translated&&<p className="task-help translation-reveal" lang="en">{taskHelp}</p>}{item.hint&&<details><summary>Mostra un indizio {translated&&"· Show a hint"}</summary><p>{item.hint}</p></details>}
      {item.type==="listen"&&<button className="listen-button" onClick={listen}>▶ {bi(translated,"Ascolta lentamente","Listen slowly")}</button>}
      {(item.type==="input"||item.type==="listen")&&<textarea aria-labelledby={`practice-prompt-${item.id}`} className="answer-box" value={answer} onChange={e=>setAnswer(e.target.value)} placeholder={bi(translated,"Scrivi qui…","Write here…")} disabled={result!==null}/>}
      {(item.type==="mcq"||item.type==="reading")&&<div className="options" role="radiogroup" aria-labelledby={`practice-prompt-${item.id}`}>{item.options?.map(o=>{const selected=answer===o;return <button type="button" role="radio" aria-checked={selected} disabled={result!==null} key={o} className={result===null?(selected?"selected":""):normalise(o)===normalise(item.answer)?"correct":normalise(o)===normalise(answer)?"wrong":"muted"} onClick={()=>setAnswer(o)}><span>{selected?"●":"○"}</span>{o}</button>})}</div>}
      {item.type==="reorder"&&<><div className="built-sentence">{built.length?built.map((w,i)=><button key={`${w}${i}`} onClick={()=>setBuilt(built.filter((_,x)=>x!==i))}>{w}</button>):<span>{bi(translated,"Tocca le tessere per costruire la frase.","Tap the tiles to build the sentence.")}</span>}</div><div className="word-tiles">{item.options?.map((w,i)=><button key={`${w}${i}`} disabled={built.filter(x=>x===w).length>=item.options!.filter(x=>x===w).length} onClick={()=>setBuilt([...built,w])}>{w}</button>)}</div></>}
      {item.type==="speak"&&<SpeakingBox value={answer} setValue={setAnswer} disabled={result!==null} translated={translated}/>}
      {result===null&&item.type!=="speak"&&<button className="primary submit-answer" onClick={submit}>{bi(translated,"Controlla","Check")} →</button>}
      {result===null&&item.type==="speak"&&<div className="self-grade"><button className="secondary" onClick={()=>selfGrade(false)}>{bi(translated,"Serve ancora pratica","I need more practice")}</button><button className="primary" onClick={()=>selfGrade(true)}>{bi(translated,"Obiettivo raggiunto","Goal achieved")}</button></div>}
      {item.type==="speak"&&answer.trim()&&<button className="ai-button" disabled={waiting} onClick={evaluate}>{waiting?bi(translated,"Correzione…","Reviewing…"):`✦ ${bi(translated,"Correzione locale","Local review")}`}</button>}
      {feedback&&<div className="ai-feedback" role="status" aria-live="polite"><span>{feedback.evaluator==="ai"?"FEEDBACK AI":"FEEDBACK RUBRICA LOCALE"} · {feedback.score||"—"}/100</span><strong>{feedback.summary}</strong>{feedback.corrections?.map((c:string)=><p key={c}>→ {c}</p>)}{feedback.betterItalian&&<blockquote>{feedback.betterItalian}</blockquote>}<small>{feedback.nextStep}</small></div>}
      {result!==null&&<div className={`feedback ${result?"good":"bad"}`} role="status" aria-live="polite"><strong>{result?"Perfetto!":"Non ancora."}{translated&&<small>{result?" · Correct":" · Not quite yet"}</small>}</strong><p>{item.explanation}</p>{!result&&<p><b>Risposta · Answer:</b> {item.answer}</p>}<CopyButton text={item.answer}/><button className="primary" onClick={next}>{index===session.length-1?bi(translated,"Vedi il risultato","View result"):bi(translated,"Prossimo esercizio","Next exercise")} →</button></div>}
    </article>
  </section>;
}

function SpeakingBox({value,setValue,disabled,translated}:{value:string;setValue:(v:string)=>void;disabled:boolean;translated:boolean}){
  const [recording,setRecording]=useState(false),[url,setUrl]=useState(""); const recorder=useRef<MediaRecorder|null>(null),chunks=useRef<Blob[]>([]);
  const toggle=async()=>{if(recording){recorder.current?.stop();setRecording(false);return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const r=new MediaRecorder(stream);chunks.current=[];r.ondataavailable=e=>chunks.current.push(e.data);r.onstop=()=>{setUrl(URL.createObjectURL(new Blob(chunks.current,{type:"audio/webm"})));stream.getTracks().forEach(t=>t.stop())};r.start();recorder.current=r;setRecording(true)}catch{alert("Microphone access is needed to record your answer.")}};
  return <div className="speaking-box"><div><button className={recording?"record live":"record"} onClick={toggle}>{recording?bi(translated,"■ Ferma registrazione","■ Stop recording"):bi(translated,"● Registra la risposta","● Record your answer")}</button>{url&&<audio src={url} controls/>}</div><label>{bi(translated,"Trascrivi o scrivi la risposta per ricevere feedback","Transcribe or type your answer to receive feedback")}<textarea className="answer-box" value={value} onChange={e=>setValue(e.target.value)} placeholder="Mi chiamo… / Nella mia famiglia…" disabled={disabled}/></label></div>;
}

function Lessons({content,learner,open,start,translated}:{content:Content;learner:LearnerState;open:(l:Lesson)=>void;start:(id:string)=>void;translated:boolean}){
  const [q,setQ]=useState(""),[course,setCourse]=useState(0), list=content.lesson.filter(lesson=>(!course||lesson.course===course)&&`${lesson.title} ${lesson.subtitle} ${lesson.topics}`.toLowerCase().includes(q.toLowerCase()));
  const measured=content.lesson.map(lesson=>lessonScore(learner,lesson.id).score).filter((value):value is number=>value!==null), mean=measured.length?Math.round(measured.reduce((sum,value)=>sum+value,0)/measured.length):null;
  return <section className="library page-width page-top"><div className="library-title"><div><p className="eyebrow">28 LESSON HUBS · IL TUO ARCHIVIO IMPERIAL {translated&&"· YOUR IMPERIAL ARCHIVE"}</p><h1>{bi(translated,"Le tue lezioni","Your lessons")}</h1><p>La padronanza appare solo dopo una prova: ciò che non hai tentato resta “da misurare”, non debole.</p>{translated&&<p className="translation-line translation-reveal">Mastery appears only after evidence; untouched material stays unmeasured, not weak.</p>}</div><div className="archive-seal"><strong>{mean===null?"—":`${mean}%`}</strong><span>{measured.length} {bi(translated,"lezioni misurate","lessons measured")}</span></div></div><div className="filters"><div className="segmented">{[[0,"Tutte","All"],[1,"Corso 1","Course 1"],[2,"Corso 2","Course 2"]].map(([i,it,en])=><button key={i} className={course===i?"active":""} onClick={()=>setCourse(Number(i))}>{bi(translated,String(it),String(en))}</button>)}</div><label className="search"><span className="sr-only">Cerca lezioni · Search lessons</span>⌕<input value={q} onChange={event=>setQ(event.target.value)} placeholder={bi(translated,"Cerca tema o grammatica…","Search topics or grammar…")}/></label></div><div className="lesson-grid">{list.map(lesson=>{const result=lessonScore(learner,lesson.id);return <article className="lesson-card" key={lesson.id}><button className="lesson-open" onClick={()=>open(lesson)}><div className="lesson-top"><span className={`course-dot c${lesson.course}`}>C{lesson.course}</span><span>{bi(translated,"SETT.","WEEK")} {lesson.week}</span><strong>{result.score===null?bi(translated,"DA MISURARE","UNMEASURED"):`${result.score}%`}</strong></div><h2>{lesson.title}</h2>{translated&&<p className="translation-reveal">{lesson.subtitle}</p>}<small className="can-do">SO FARE · {lesson.canDoIt}</small>{translated&&<small className="can-do-en translation-reveal">CAN DO · {lesson.canDo}</small>}<div className="mini-mastery" aria-label={`${result.coverage} di 7 abilità misurate`}>{skills.map(skill=>{const item=masteryFor(learner,lesson.id,skill);return <i key={skill} title={item.attempts?`${skill}: ${accuracy(item.attempts,item.correct)}%`:`${skill}: ${translated?"unmeasured":"da misurare"}`} className={item.attempts?"":"unmeasured"} style={{height:`${item.attempts?Math.max(5,accuracy(item.attempts,item.correct)):5}%`}}/>})}</div></button><button className="lesson-test" onClick={()=>start(lesson.id)}>{bi(translated,"Avvia test lezione","Start lesson check")} →</button></article>})}</div></section>;
}

function Roadmap({content,learner,save,start,translated}:{content:Content;learner:LearnerState;save:SaveLearner;start:(id:string)=>void;translated:boolean}){
  const next=studyPlanDays.find(day=>!isDayComplete(learner,day))||studyPlanDays.at(-1)!, [selectedWeek,setSelectedWeek]=useState(next.week),[selectedDay,setSelectedDay]=useState(next.day);
  const week=studyPlanWeeks.find(item=>item.week===selectedWeek)||studyPlanWeeks[0], day=studyPlanDays.find(item=>item.day===selectedDay)||week.days[0], progress=dayProgress(learner,day.day);
  const completedTasks=studyPlanDays.reduce((sum,item)=>sum+dayProgress(learner,item.day).completedTaskIds.filter(id=>item.tasks.some(task=>task.id===id)).length,0),totalTasks=studyPlanDays.length*4,percent=Math.round(completedTasks/totalTasks*100);
  const completedMinutes=Object.values(learner.planDays).reduce((sum,item)=>sum+(item.actualMinutes||0),0), remainingMinutes=Math.max(0,plannedMinutes-completedMinutes),remainingDays=Math.max(1,56-studyPlanDays.filter(item=>isDayComplete(learner,item)).length);
  const updateDay=(updates:Partial<ReturnType<typeof dayProgress>>,meaningful=false)=>{const today=localDateKey();save(state=>{const latest=dayProgress(state,day.day);return{...state,studyDays:meaningful&&!state.studyDays.includes(today)?[...state.studyDays,today]:state.studyDays,planDays:{...state.planDays,[String(day.day)]:{...latest,...updates}}}})};
  const toggle=(taskId:string)=>{const today=localDateKey();save(state=>{const latest=dayProgress(state,day.day),done=latest.completedTaskIds.includes(taskId),ids=done?latest.completedTaskIds.filter(id=>id!==taskId):[...latest.completedTaskIds,taskId];return{...state,studyDays:done||state.studyDays.includes(today)?state.studyDays:[...state.studyDays,today],planDays:{...state.planDays,[String(day.day)]:{...latest,completedTaskIds:ids,completedAt:ids.length===day.tasks.length?new Date().toISOString():undefined}}}})};
  const pickWeek=(number:number)=>{const chosen=studyPlanWeeks.find(item=>item.week===number)!;setSelectedWeek(number);setSelectedDay(chosen.days.find(item=>!isDayComplete(learner,item))?.day||chosen.days[0].day)};
  const status=(item:StudyPlanDay)=>{const p=dayProgress(learner,item.day),count=p.completedTaskIds.filter(id=>item.tasks.some(task=>task.id===id)).length;if(count===4&&(!item.scored||p.testScore!==undefined))return"verified";if(count===4)return"done";if(count)return"progress";return"new"};
  const linked=content.lesson.find(item=>item.id===day.lessonId), scheduled=planDate(learner.planStart,day.day);
  return <section className="roadmap plan-view page-width page-top" data-tour="plan">
    <div className="plan-hero"><div><p className="eyebrow">56 GIORNI · {Math.round(plannedMinutes/60)} ORE PIANIFICATE · A1 CONSOLIDAMENTO</p><h1>Il tuo quaderno di rotta</h1><p>Il libro resta nell’ordine originale. Ogni giorno aggiunge richiamo, correzione e una prova concreta; le attività spuntate e le note vengono salvate.</p>{translated&&<p className="translation-line translation-reveal">The book stays in its printed order. Every day adds retrieval, correction and a real output; check-offs and notes are saved.</p>}<div className="edition-note"><strong>Nuovo Espresso 1 · edizione 2014</strong><span>Le pagine corrispondono alla tua copia di 239 pagine, non a Nuovo Espresso Plus 1.</span>{translated&&<small className="translation-reveal">Page references match your 239-page copy, not the revised Plus edition.</small>}</div></div><div className="plan-dial" style={{"--p":`${percent}%`} as React.CSSProperties}><strong>{percent}%</strong><span>{completedTasks}/{totalTasks} blocchi</span></div></div>
    <div className="plan-toolbar"><label><span>{bi(translated,"INIZIO DEL PIANO","PLAN START")}</span><input type="date" value={learner.planStart} onChange={event=>{const value=event.target.value||localDateKey();save(state=>({...state,planStart:value}))}}/></label><div><span>{bi(translated,"FINE PREVISTA","EXPECTED FINISH")}</span><strong>{planDate(learner.planStart,56).toLocaleDateString("it-IT",{day:"numeric",month:"short",year:"numeric"})}</strong></div><div><span>{bi(translated,"RITMO DA QUI","PACE FROM HERE")}</span><strong>{Math.ceil(remainingMinutes/remainingDays)} {bi(translated,"min/giorno","min/day")}</strong></div><button className="secondary" onClick={()=>{setSelectedWeek(next.week);setSelectedDay(next.day)}}>{bi(translated,"Vai al prossimo giorno","Go to next day")} →</button></div>
    <div className="week-tabs" role="tablist" aria-label="Settimane del piano · Plan weeks">{studyPlanWeeks.map(item=>{const done=item.days.filter(value=>isDayComplete(learner,value)).length;return <button role="tab" aria-selected={selectedWeek===item.week} key={item.week} className={selectedWeek===item.week?"active":""} onClick={()=>pickWeek(item.week)}><span>{bi(translated,"SETT.","WEEK")} {item.week}</span><strong>{item.titleIt}</strong>{translated&&<em>{item.titleEn}</em>}<small>{done}/7 {item.heavy?bi(translated,"· intensa","· heavy"):""}</small></button>})}</div>
    <article className="week-brief"><div><span>{bi(translated,"SETTIMANA","WEEK")} {String(week.week).padStart(2,"0")}</span><h2>{week.titleIt}</h2>{translated&&<h3 className="translation-reveal">{week.titleEn}</h3>}</div><div><small>{bi(translated,"OBIETTIVO","GOAL")}</small><p>{week.goalIt}</p>{translated&&<em className="translation-reveal">{week.goalEn}</em>}</div><div><small>{bi(translated,"MAPPA DEL LIBRO","BOOK MAP")}</small><p>{week.bookMap}</p></div><div><small>{bi(translated,"PROVA DELLA SETTIMANA","WEEKLY EVIDENCE TASK")}</small><p>{week.proofIt}</p>{translated&&<em className="translation-reveal">{week.proofEn}</em>}</div></article>
    <div className="plan-workspace"><aside className="day-list" aria-label={`Giorni della settimana ${week.week}`}>{week.days.map(item=>{const state=status(item),date=planDate(learner.planStart,item.day);return <button key={item.day} className={`${selectedDay===item.day?"active":""} ${state}`} onClick={()=>setSelectedDay(item.day)}><span>{String(item.day).padStart(2,"0")}</span><div><strong>{item.titleIt}</strong><small>{date.toLocaleDateString("it-IT",{weekday:"short",day:"numeric",month:"short"})} · {item.tasks.reduce((sum,task)=>sum+task.minutes,0)} min</small></div><i aria-label={state}>{state==="verified"?"✓":state==="done"?"•":state==="progress"?"◐":"○"}</i></button>})}</aside>
      <article className="day-detail"><header><div><p className="eyebrow">GIORNO {day.day} · {scheduled.toLocaleDateString("it-IT",{weekday:"long",day:"numeric",month:"long"})}</p><h2>{day.titleIt}</h2>{translated&&<p className="translation-line translation-reveal">{day.titleEn}</p>}</div><div className="day-badges">{day.checkpoint&&<span>CHECKPOINT</span>}{day.light&&<span>GIORNO LEGGERO</span>}<span>{day.source}</span></div></header><div className="task-checklist">{day.tasks.map((task,index)=>{const done=progress.completedTaskIds.includes(task.id);return <label key={task.id} className={done?"done":""}><input type="checkbox" checked={done} onChange={()=>toggle(task.id)}/><span className="task-number">{String(index+1).padStart(2,"0")}</span><span><small>{task.titleIt}{translated&&` · ${task.titleEn}`}</small><strong>{task.detailIt}</strong>{translated&&<em className="translation-reveal">{task.detailEn}</em>}</span><b>{task.minutes}<small>min</small></b></label>})}</div>
      <div className="day-log" key={day.day}><label><span>{bi(translated,"MINUTI REALI","ACTUAL MINUTES")}</span><input type="number" min="0" max="300" defaultValue={progress.actualMinutes||""} placeholder={String(day.tasks.reduce((sum,task)=>sum+task.minutes,0))} onBlur={event=>{const minutes=Math.max(0,Number(event.target.value||0));updateDay({actualMinutes:minutes,workedOn:minutes?localDateKey():undefined},minutes>0)}}/></label>{day.scored&&<label><span>{bi(translated,"PUNTEGGIO PRIMO TENTATIVO","FIRST-ATTEMPT SCORE")}</span><div className="score-input"><input type="number" min="0" max="100" defaultValue={progress.testScore??""} onBlur={event=>updateDay({testScore:event.target.value===""?undefined:Math.max(0,Math.min(100,Number(event.target.value)))},event.target.value!=="")}/><b>/100</b></div></label>}<fieldset><legend>{bi(translated,"SICUREZZA DOPO LA SESSIONE","CONFIDENCE AFTER THE SESSION")}</legend>{[1,2,3,4,5].map(value=><button type="button" key={value} aria-pressed={progress.confidence===value} className={progress.confidence===value?"active":""} onClick={()=>updateDay({confidence:value},true)} aria-label={`${bi(translated,"Sicurezza","Confidence")} ${value} ${bi(translated,"su","of")} 5`}>{value}</button>)}</fieldset><label className="reflection"><span>{bi(translated,"NOTA / ERRORE DA RIPRENDERE","NOTE / ERROR TO REVISIT")}</span><textarea defaultValue={progress.note} placeholder={bi(translated,"Una frase concreta: cosa torna fra +1, +3 o +7 giorni?","One concrete sentence: what returns in +1, +3 or +7 days?")} onBlur={event=>updateDay({note:event.target.value})}/></label></div>
      <footer className="day-actions"><span>{progress.completedTaskIds.length}/4 {bi(translated,"blocchi completati · stato","blocks complete · status")}: <b>{status(day)==="verified"?bi(translated,"verificato","verified"):status(day)==="done"?bi(translated,"completato, manca la prova","complete, evidence pending"):status(day)==="progress"?bi(translated,"in corso","in progress"):bi(translated,"non iniziato","not started")}</b></span>{linked&&<button className="primary" onClick={()=>start(linked.id)}>{bi(translated,"Apri pratica","Open practice")}: {linked.title} →</button>}</footer></article>
    </div>
    <section className="resource-shelf"><div><p className="eyebrow">{bi(translated,"FONTI E MATERIALI","SOURCES AND MATERIALS")}</p><h2>Il libro orienta. Il portale fa praticare.</h2><p>Le pagine sono riferimenti, non copie degli esercizi. La scansione PDFCoffee non viene pubblicata né collegata.</p>{translated&&<p className="translation-line translation-reveal">The book sets the route and the portal supplies practice. Page numbers are references, not reproduced exercises; the PDFCoffee scan is neither published nor linked.</p>}</div><div className="resource-links">{officialResources.map(resource=><a key={resource.href} href={resource.href} target="_blank" rel="noreferrer"><span>{bi(translated,"FONTE UFFICIALE","OFFICIAL SOURCE")} ↗</span><strong>{resource.label}</strong>{translated&&<small className="translation-reveal">{resource.labelEn}</small>}</a>)}<a href="/downloads/Parliamo_Practice_Workbook.pdf"><span>{bi(translated,"PDF PERSONALE","YOUR PDF")} ↓</span><strong>Quaderno di pratica</strong><small>{translated?"Your printable practice workbook":"PDF stampabile"}</small></a><a href="/downloads/Parliamo_Reading_Workbook.pdf"><span>{bi(translated,"PDF PERSONALE","YOUR PDF")} ↓</span><strong>Quaderno di lettura</strong><small>{translated?"Your printable reading workbook":"PDF stampabile"}</small></a></div></section>
  </section>;
}

function LabsHub({content,learner,save,record,translated}:{content:Content;learner:LearnerState;save:SaveLearner;record:(e:Exercise,c:boolean,ms:number,xp:number)=>void;translated:boolean}){
  const [lab,setLab]=useState<"reading"|"vocab"|"prepositions"|"games">("vocab");
  return <div className="labs-hub page-top" data-tour="labs"><section className="lab-intro page-width"><div><p className="eyebrow">QUATTRO LABORATORI · UN SOLO OBIETTIVO {translated&&"· FOUR LABS, ONE PURPOSE"}</p><h1>{bi(translated,"Richiama, ascolta, costruisci.","Recall, listen, build.")}</h1><p>Usa questi strumenti dentro il piano: le carte seguono le scadenze, gli esercizi alimentano la mappa di padronanza.</p>{translated&&<p className="translation-line translation-reveal">Use these tools inside the plan: cards follow due dates and practice updates your mastery map.</p>}</div><div className="lab-summary"><strong>{content.vocab.length}</strong><span>{bi(translated,"parole","words")}</span><strong>{content.reading.length}</strong><span>{bi(translated,"letture","readings")}</span><strong>3</strong><span>{bi(translated,"giochi","games")}</span></div></section><nav className="lab-nav page-width" aria-label="Laboratori · Labs">{[["vocab","Parole","Words"],["reading","Letture","Readings"],["prepositions","Preposizioni","Prepositions"],["games","Giochi","Games"]].map(([id,it,en])=><button key={id} className={lab===id?"active":""} onClick={()=>setLab(id as typeof lab)}>{bi(translated,it,en)}</button>)}</nav>{lab==="vocab"&&<VocabLab words={content.vocab} learner={learner} save={save} translated={translated}/>} {lab==="reading"&&<Reader readings={content.reading} translated={translated}/>} {lab==="prepositions"&&<PrepLab items={content.preposition} record={record} translated={translated}/>} {lab==="games"&&<GamesHub content={content} record={record} translated={translated}/>}<section className="lab-coverage page-width"><CurriculumCoverage content={content} translated={translated}/></section></div>;
}

function Reader({readings,translated}:{readings:Reading[];translated:boolean}){const [index,setIndex]=useState(0),[shown,setShown]=useState<number[]>([]);const r=readings[index],revealed=translated?r.sentences.length:shown.length;return <section className="reader page-width page-top"><div className="reader-head"><div><p className="eyebrow">LETTURA BILINGUE · RETRIEVAL FIRST</p><h1>Leggi. Inferisci. Rivela.</h1>{translated&&<p className="translation-line translation-reveal">Read first, infer from context, then reveal the English only when needed.</p>}</div>{translated?<div className="reader-mode-note translation-reveal"><span>IT+EN</span><div><strong>Translations are visible</strong><small>Switch to Immersion to reveal them sentence by sentence.</small></div></div>:<button className="secondary" onClick={()=>setShown(shown.length===r.sentences.length?[]:r.sentences.map((_,i)=>i))}>{shown.length===r.sentences.length?"Nascondi tutte":"Rivela tutte"}</button>}</div><div className="reader-layout"><aside>{readings.map((x,i)=><button key={x.id} className={index===i?"active":""} onClick={()=>{setIndex(i);setShown([])}}><span>{String(i+1).padStart(2,"0")}</span><div><strong>{x.title}</strong><small>{x.level} · {x.theme}</small></div></button>)}</aside><article className="reading-paper"><div className="reading-progress"><span>{revealed}/{r.sentences.length} traduzioni {translated&&"· translations"}</span><i><b style={{width:`${revealed/r.sentences.length*100}%`}}/></i></div><h2>{r.title}</h2><div className="sentences">{r.sentences.map(([it,en],i)=><button key={it} className={translated||shown.includes(i)?"revealed":""} onClick={()=>setShown(shown.includes(i)?shown.filter(x=>x!==i):[...shown,i])}><span className="sentence-number">{i+1}</span><span><strong>{it}</strong>{(translated||shown.includes(i))?<em className="translation-reveal">{en}</em>:<small>Tocca dopo aver inferito</small>}</span></button>)}</div></article></div></section>}

function VocabLab({words,learner,save,translated}:{words:Vocab[];learner:LearnerState;save:SaveLearner;translated:boolean}){
  const due=[...words].filter(word=>!learner.cards[word.id]||new Date(learner.cards[word.id].due)<=new Date()).sort((a,b)=>(learner.cards[a.id]?.due||"").localeCompare(learner.cards[b.id]?.due||"")),[flip,setFlip]=useState(false), card=due[0]||words[0];
  const rate=(quality:number)=>{const today=localDateKey();save(state=>{const previous=state.cards[card.id]||{interval:0,due:new Date().toISOString(),ease:2.5,reviews:0},interval=[0,1,Math.max(3,Math.round(previous.interval*1.8)),Math.max(7,Math.round(previous.interval*2.5))][quality];return{...state,xp:state.xp+[1,2,4,6][quality],studyDays:state.studyDays.includes(today)?state.studyDays:[...state.studyDays,today],cards:{...state.cards,[card.id]:{interval,due:new Date(Date.now()+interval*864e5).toISOString(),ease:Math.max(1.3,previous.ease+(quality-1.5)*.1),reviews:previous.reviews+1}}}});setFlip(false)};
  return <section className="vocab-view page-width page-top"><div className="library-title"><div><p className="eyebrow">RICHIAMO DISTANZIATO · +1 · +3 · +7 · +14</p><h1>Parole che restano</h1><p>{due.length} carte previste ora. Richiamale prima di girarle.</p>{translated&&<p className="translation-line translation-reveal">Recall the Italian before flipping; misses return sooner and successful cards wait longer.</p>}</div><div className="archive-seal ochre"><strong>{words.length}</strong><span>parole A1</span></div></div>{due.length===0?<article className="review-complete"><span>✓</span><div><p className="eyebrow">CODA COMPLETATA</p><h2>Per oggi basta così.</h2><p>Le prossime carte riappariranno alla loro scadenza. Usa il tempo risparmiato per ascolto o conversazione.</p>{translated&&<p className="translation-line translation-reveal">Your due queue is clear. Use the saved time for listening or conversation.</p>}</div></article>:<div className="vocab-layout"><aside className="deck-stats"><div><strong>{due.length}</strong><span>scadute {translated&&"· due"}</span></div><div><strong>{Object.keys(learner.cards).length}</strong><span>in memoria {translated&&"· scheduled"}</span></div><div><strong>{learner.cards[card.id]?.reviews||0}</strong><span>ripassi {translated&&"· reviews"}</span></div><p>La coda non salta più le carte: la prossima dovuta resta sempre in cima.</p>{translated&&<p className="micro-translation translation-reveal">The due queue always keeps the next card at the top.</p>}</aside><div><button className={`flashcard ${flip?"flipped":""}`} onClick={()=>setFlip(!flip)}><span className="flash-topic">{card.topic}</span>{!flip?<><small>ITALIANO</small><strong>{card.italian}</strong><em>Tocca per girare {translated&&"· Tap to flip"}</em></>:<><small>ENGLISH</small><strong>{card.english}</strong><blockquote><span>{card.example}</span><small className="translation-reveal">{card.exampleEn}</small></blockquote></>}</button><div className="ratings">{[["Di nuovo","Again"],["Difficile","Hard"],["Bene","Good"],["Facile","Easy"]].map(([it,en],quality)=><button key={it} disabled={!flip} onClick={()=>rate(quality)}>{it}{translated&&<small>{en}</small>}</button>)}</div></div></div>}</section>;
}

function PrepLab({items,record,translated}:{items:Preposition[];record:(e:Exercise,c:boolean,ms:number,xp:number)=>void;translated:boolean}){
  const [i,setI]=useState(0),[choice,setChoice]=useState("");const started=useRef(Date.now()),item=items[i%items.length];
  const options=useMemo(()=>[item.answer,...["a","in","al","alla","nel","nella","sul","degli","dalla","nello","dagli","delle","all’","sulla"].filter(x=>x!==item.answer).sort(()=>Math.random()-.5).slice(0,7)].sort(()=>Math.random()-.5),[item]);
  const choose=(o:string)=>{if(choice)return;setChoice(o);const e:Exercise={id:item.id,lessonId:"c2w07",skill:"grammar",type:"mcq",prompt:item.full,answer:item.answer,explanation:item.hint};record(e,o===item.answer,Date.now()-started.current,o===item.answer?7:2)};
  return <section className="prep-view page-width page-top"><div className="reader-head"><div><p className="eyebrow">LABORATORIO GENERATIVO</p><h1>Costruisci, non indovinare</h1><p>Luogo + articolo + fusione: il database ricorda ogni combinazione debole.</p>{translated&&<p className="translation-line translation-reveal">Build the form from place, article and contraction—the database remembers weak combinations.</p>}</div></div><article className="prep-board"><div className="prep-formula"><span>{item.before}</span><strong>{choice||"___"}</strong><span>{item.target}</span></div>{translated&&<p className="prep-formula-en translation-reveal">{item.beforeEn} <b>{choice||"___"}</b> {item.targetEn}</p>}<p className="prep-hint">Indizio: {item.hint}{translated&&<small className="translation-reveal">Hint: {item.hintEn}</small>}</p><div className="prep-pieces">{options.map(o=><button key={o} className={choice?(o===item.answer?"correct":o===choice?"wrong":"muted"):""} onClick={()=>choose(o)}>{o}</button>)}</div>{choice&&<div className={`prep-feedback ${choice===item.answer?"good":"bad"}`}><strong>{item.full}</strong>{translated&&<small className="translation-reveal">{item.fullEn}</small>}<CopyButton text={item.full}/><button className="primary" onClick={()=>{setChoice("");setI(i+1);started.current=Date.now()}}>Prossima {translated&&"· Next"} →</button></div>}</article></section>
}

function GamesHub({content,record,translated}:{content:Content;record:(e:Exercise,c:boolean,ms:number,xp:number)=>void;translated:boolean}){
  const [game,setGame]=useState<"match"|"verbs"|"intruder">("match");
  return <section className="games-view page-width page-top"><div className="library-title"><div><p className="eyebrow">MICRO-GIOCHI · DATI DAL CURRICOLO</p><h1>Gioca con uno scopo</h1><p>Tre sfide brevi per recuperare parole, coniugare e riconoscere categorie.</p>{translated&&<p className="translation-line translation-reveal">Three focused games for vocabulary recall, verb production and category recognition.</p>}</div><div className="archive-seal ochre"><strong>3</strong><span>sfide mirate</span></div></div><div className="game-tabs">{[["match","Abbina"],["verbs","Corsa dei verbi"],["intruder","Trova l’intruso"]].map(([id,label])=><button key={id} className={game===id?"active":""} onClick={()=>setGame(id as typeof game)}>{label}</button>)}</div>{game==="match"&&<MatchGame words={content.vocab} record={record} translated={translated}/>} {game==="verbs"&&<VerbGame verbs={content.verb} record={record} translated={translated}/>} {game==="intruder"&&<IntruderGame words={content.vocab} record={record} translated={translated}/>}</section>
}

function MatchGame({words,record,translated}:{words:Vocab[];record:(e:Exercise,c:boolean,ms:number,xp:number)=>void;translated:boolean}){
  const [round,setRound]=useState(0),[left,setLeft]=useState<string|null>(null),[right,setRight]=useState<string|null>(null),[matched,setMatched]=useState<string[]>([]),[message,setMessage]=useState("");const started=useRef(Date.now());
  const cards=useMemo(()=>Array.from({length:4},(_,i)=>words[(round*7+i*11)%words.length]),[round,words]);
  const english=useMemo(()=>[...cards].sort((a,b)=>((a.id.charCodeAt(a.id.length-1)+round)%7)-((b.id.charCodeAt(b.id.length-1)+round)%7)),[cards,round]);
  const evaluate=(l:string,r:string)=>{const ok=l===r;const word=cards.find(w=>w.id===l)!;record({id:`game-match-${word.id}`,lessonId:"vocab",skill:"vocabulary",type:"mcq",prompt:word.italian,answer:word.english,explanation:word.example},ok,Date.now()-started.current,ok?6:1);setMessage(ok?`Perfetto — coppia trovata!${translated?" · Perfect—match found!":""}`:`Non ancora: guarda e riprova.${translated?" · Not yet—look again and retry.":""}`);if(ok)setMatched([...matched,l]);window.setTimeout(()=>{setLeft(null);setRight(null);setMessage("");started.current=Date.now()},650)};
  const chooseLeft=(id:string)=>{if(matched.includes(id))return;setLeft(id);if(right)evaluate(id,right)};const chooseRight=(id:string)=>{if(matched.includes(id))return;setRight(id);if(left)evaluate(left,id)};
  return <article className="game-board"><div className="game-instructions"><span>01</span><div><h2>Abbina senza tradurre parola per parola</h2><p>Scegli una parola italiana e il suo significato inglese.</p>{translated&&<small>Choose one Italian word and its English match.</small>}</div><strong>{matched.length}/4</strong></div><div className="match-grid"><div>{cards.map(w=><button key={w.id} disabled={matched.includes(w.id)} className={left===w.id?"selected":""} onClick={()=>chooseLeft(w.id)}>{w.italian}</button>)}</div><div>{english.map(w=><button key={w.id} disabled={matched.includes(w.id)} className={right===w.id?"selected":""} onClick={()=>chooseRight(w.id)}>{w.english}</button>)}</div></div><div className="game-status"><span>{message||`Fai la prima coppia.${translated?" · Make the first match.":""}`}</span>{matched.length===4&&<button className="primary" onClick={()=>{setRound(round+1);setMatched([]);setLeft(null);setRight(null)}}>Nuovo gruppo {translated&&"· New set"} →</button>}</div></article>
}

function VerbGame({verbs,record,translated}:{verbs:Content["verb"];record:(e:Exercise,c:boolean,ms:number,xp:number)=>void;translated:boolean}){
  const pronouns=["io","tu","lui / lei","noi","voi","loro"],[round,setRound]=useState(0),[answer,setAnswer]=useState(""),[result,setResult]=useState<null|boolean>(null);const started=useRef(Date.now()),verb=verbs[(round*7)%verbs.length],person=round%6,correct=verb.forms[person];
  const submit=()=>{if(!answer.trim()||result!==null)return;const ok=normalise(answer)===normalise(correct);setResult(ok);record({id:`game-verb-${verb.id}-${person}`,lessonId:"verbs",skill:"grammar",type:"input",prompt:`${pronouns[person]} · ${verb.infinitive}`,answer:correct,explanation:`${pronouns[person]} ${correct}`},ok,Date.now()-started.current,ok?8:2)};
  return <article className="game-board verb-game"><div className="game-instructions"><span>02</span><div><h2>Produci la forma, non riconoscerla</h2><p>Niente opzioni: coniuga il verbo per il soggetto.</p>{translated&&<small>No options: produce the correct verb form.</small>}</div><strong>{round+1}</strong></div><div className="verb-prompt"><span>{pronouns[person]}</span><strong>{verb.infinitive}</strong>{translated&&<small>{verb.english}</small>}</div><div className="verb-answer"><input aria-label={bi(translated,`Forma di ${verb.infinitive} per ${pronouns[person]}`,`${verb.infinitive} form for ${pronouns[person]}`)} value={answer} disabled={result!==null} onChange={e=>setAnswer(e.target.value)} onKeyDown={e=>e.key==="Enter"&&submit()} placeholder="Scrivi la forma…"/><button className="primary" onClick={submit}>Controlla {translated&&"· Check"}</button></div>{result!==null&&<div className={`game-feedback ${result?"good":"bad"}`} role="status" aria-live="polite"><strong>{result?"Esatto!":"Quasi."}{translated&&(result?" · Correct!":" · Almost.")} {pronouns[person]} {correct}</strong><button onClick={()=>{setRound(round+1);setAnswer("");setResult(null);started.current=Date.now()}}>Prossimo verbo {translated&&"· Next verb"} →</button></div>}</article>
}

function IntruderGame({words,record,translated}:{words:Vocab[];record:(e:Exercise,c:boolean,ms:number,xp:number)=>void;translated:boolean}){
  const topics=useMemo(()=>[...new Set(words.map(w=>w.topic))].filter(t=>words.filter(w=>w.topic===t).length>=3),[words]);const [round,setRound]=useState(0),[choice,setChoice]=useState("");const started=useRef(Date.now()),topic=topics[round%topics.length],other=topics[(round+3)%topics.length];
  const options=useMemo(()=>{const same=words.filter(w=>w.topic===topic),different=words.filter(w=>w.topic===other);return [...Array.from({length:3},(_,index)=>same[(round+index)%same.length]),different[round%different.length]].sort((a,b)=>a.id.localeCompare(b.id)*(round%2?1:-1))},[round,topic,other,words]);const odd=options.find(w=>w.topic===other)!;
  const choose=(word:Vocab)=>{if(choice)return;setChoice(word.id);const ok=word.id===odd.id;record({id:`game-intruder-${round}`,lessonId:"vocab",skill:"vocabulary",type:"mcq",prompt:`Categoria: ${topic}`,answer:odd.italian,explanation:`${odd.italian} appartiene a ${other}.`},ok,Date.now()-started.current,ok?7:2)};
  return <article className="game-board"><div className="game-instructions"><span>03</span><div><h2>Trova la parola fuori categoria</h2><p>Tre parole appartengono a “{topic}”. Quale no?</p>{translated&&<small>Three words belong to “{topic}”. Which one does not?</small>}</div><strong>{round+1}</strong></div><div className="intruder-grid">{options.map(w=><button key={w.id} className={choice?(w.id===odd.id?"correct":w.id===choice?"wrong":"muted"):""} onClick={()=>choose(w)}><strong>{w.italian}</strong>{translated&&<small>{w.english}</small>}</button>)}</div>{choice&&<div className="game-status"><span><b>{odd.italian}</b> appartiene a “{other}”. {translated&&<small>· It belongs to “{other}”.</small>}</span><button className="primary" onClick={()=>{setRound(round+1);setChoice("");started.current=Date.now()}}>Altra categoria {translated&&"· Another category"} →</button></div>}</article>
}

const cefrLanes=[
  {id:"listening",it:"Ascolto",en:"Listening",a1:"Capire senso globale e 3/4 dettagli in due clip lente e chiare.",a1En:"Understand the gist and 3/4 details in two slow, clear clips.",a2:"Capire un messaggio semplice di 60–90 secondi e 4/6 dettagli.",a2En:"Understand a simple 60–90 second message and 4/6 details."},
  {id:"reading",it:"Lettura",en:"Reading",a1:"Trovare 4/5 informazioni in menu, orari, annunci o avvisi.",a1En:"Find 4/5 requested facts in a menu, timetable, advert or notice.",a2:"Capire scopo e informazioni prevedibili in un testo di 100–150 parole.",a2En:"Identify purpose and predictable information in a 100–150 word text."},
  {id:"interaction",it:"Interazione orale",en:"Spoken interaction",a1:"Sostenere uno scambio guidato di 3 minuti e chiedere di ripetere.",a1En:"Sustain a guided three-minute exchange and ask for repetition.",a2:"Gestire un role-play di 4 minuti con tre domande non preparate.",a2En:"Handle a four-minute role-play with three unprepared follow-up questions."},
  {id:"production",it:"Produzione orale",en:"Spoken production",a1:"Descrivere sé, casa e persone per 60–90 secondi senza copione.",a1En:"Describe yourself, home and known people for 60–90 seconds without a script.",a2:"Collegare frasi per 90–120 secondi su routine, famiglia o viaggio.",a2En:"Link phrases for 90–120 seconds about routine, family or a trip."},
  {id:"writing",it:"Scrittura",en:"Writing",a1:"Compilare un modulo e scrivere un messaggio chiaro di 40–60 parole.",a1En:"Complete a form and write a clear 40–60 word message.",a2:"Scrivere 70–100 parole collegate con e, ma e perché.",a2En:"Write 70–100 words linked with and, but and because."},
] as const;

function Analytics({content,learner,save,translated}:{content:Content;learner:LearnerState;save:SaveLearner;translated:boolean}){
  const completedDays=studyPlanDays.filter(day=>isDayComplete(learner,day)).length,actualMinutes=Object.values(learner.planDays).reduce((sum,day)=>sum+(day.actualMinutes||0),0),taskCount=studyPlanDays.reduce((sum,day)=>sum+dayProgress(learner,day.day).completedTaskIds.filter(id=>day.tasks.some(task=>task.id===id)).length,0);
  const scoredDays=studyPlanDays.filter(day=>day.scored),measuredLessons=content.lesson.filter(lesson=>lessonScore(learner,lesson.id).score!==null).length,checkpoints=scoredDays.filter(day=>dayProgress(learner,day.day).testScore!==undefined).map(day=>({day:day.day,score:dayProgress(learner,day.day).testScore!}));
  const last14=Array.from({length:14},(_,index)=>{const date=new Date();date.setDate(date.getDate()-(13-index));const key=localDateKey(date),minutes=Object.entries(learner.planDays).reduce((sum,[dayNumber,item])=>{const legacyDate=!item.workedOn?localDateKey(planDate(learner.planStart,Number(dayNumber))):"";return sum+((item.workedOn||legacyDate)===key?(item.actualMinutes||0):0)},0);return{key,label:date.toLocaleDateString("it-IT",{weekday:"short"}).slice(0,1),fullLabel:date.toLocaleDateString("it-IT",{weekday:"short",day:"numeric",month:"short"}),minutes}});
  return <section className="analytics page-width page-top" data-tour="progress"><div className="library-title"><div><p className="eyebrow">PROVE, NON SOLO PERCENTUALI {translated&&"· EVIDENCE, NOT JUST PERCENTAGES"}</p><h1>{bi(translated,"La tua mappa A1","Your A1 evidence map")}</h1><p>Completamento del piano, minuti reali, richiamo ritardato, checkpoint e prove CEFR restano separati: nessun numero singolo finge di essere “il tuo livello”.</p>{translated&&<p className="translation-line translation-reveal">Plan completion, real minutes, delayed recall, checkpoints and CEFR evidence stay separate; no single score pretends to be your level.</p>}</div><div className="archive-seal"><strong>{completedDays}</strong><span>{bi(translated,"giorni verificati","verified days")}</span></div></div><div className="metric-grid"><div><span>{bi(translated,"PIANO","PLAN")}</span><strong>{Math.round(taskCount/(studyPlanDays.length*4)*100)}%</strong><small>{taskCount}/{studyPlanDays.length*4} {bi(translated,"blocchi","blocks")}</small></div><div><span>{bi(translated,"TEMPO REALE","ACTUAL TIME")}</span><strong>{Math.round(actualMinutes/60)}h</strong><small>{bi(translated,"su","of")} {Math.round(plannedMinutes/60)}h {bi(translated,"pianificate","planned")}</small></div><div><span>{bi(translated,"PRATICA","PRACTICE")}</span><strong>{learner.attempts?`${accuracy(learner.attempts,learner.correct)}%`:"—"}</strong><small>{learner.attempts?`${learner.attempts} ${bi(translated,"tentativi","attempts")}`:bi(translated,"ancora da misurare","not yet measured")}</small></div><div><span>{bi(translated,"LEZIONI MISURATE","MEASURED LESSONS")}</span><strong>{measuredLessons}</strong><small>{bi(translated,"su 28 hub","of 28 hubs")}</small></div></div>
    <CefrTracker learner={learner} save={save} translated={translated}/>
    <section className="checkpoint-panel"><div><p className="eyebrow">CHECKPOINT</p><h2>{bi(translated,"Quattro test, sempre al primo tentativo","Four tests, always record the first attempt")}</h2><p>{bi(translated,"Le soglie 70/85 sono guide interne per decidere il ripasso, non punteggi CEFR.","The 70/85 thresholds are internal review guides, not CEFR scores.")}</p></div><div>{scoredDays.map((test,index)=>{const score=checkpoints.find(item=>item.day===test.day)?.score;return <article key={test.day} className={score===undefined?"unmeasured":score<70?"repair":score<85?"developing":"solid"}><span>TEST {index+1}</span><strong>{score===undefined?"—":`${score}%`}</strong><small>{score===undefined?bi(translated,"da fare","not done"):score<70?bi(translated,"riparazione","repair"):score<85?bi(translated,"in sviluppo","developing"):bi(translated,"solido","solid")}</small></article>})}</div></section>
    <div className="skill-dashboard">{content.skill.map(skill=>{const values=Object.entries(learner.mastery).filter(([key])=>key.endsWith(`:${skill.id}`)).map(([,value])=>value),attempts=values.reduce((sum,item)=>sum+item.attempts,0),correct=values.reduce((sum,item)=>sum+item.correct,0),pct=attempts?accuracy(attempts,correct):0;return <article key={skill.id} className={attempts?"":"unmeasured"}><div className="skill-ring" style={{"--p":`${pct}%`} as React.CSSProperties}><strong>{attempts?`${pct}%`:"—"}</strong></div><div><span>{skill.it}{translated&&` · ${skill.en}`}</span><p>{skill.targetIt}</p>{translated&&<p className="micro-translation translation-reveal">{skill.target}</p>}<small>{attempts?`${attempts} ${bi(translated,"tentativi","attempts")}`:bi(translated,"Da misurare con una prova","Unmeasured—complete an evidence task")}</small></div></article>})}</div>
    <figure className="activity-chart" aria-labelledby="activity-title"><figcaption><p className="eyebrow">ULTIMI 14 GIORNI</p><h2 id="activity-title">Minuti registrati</h2>{translated&&<p className="micro-translation translation-reveal">Logged study minutes</p>}</figcaption><div className="bars">{last14.map(day=><div key={day.key} aria-label={`${day.fullLabel}: ${day.minutes} minuti`}><small>{day.minutes}</small><i style={{height:`${Math.max(4,Math.min(100,day.minutes))}%`}}/><span>{day.label}</span></div>)}</div></figure>
    <div className="lesson-table"><div><span>Lezione {translated&&"· Lesson"}</span><span>Padronanza {translated&&"· Mastery"}</span><span>Prossima azione {translated&&"· Next action"}</span></div>{content.lesson.map(lesson=>{const result=lessonScore(learner,lesson.id);return <div key={lesson.id}><strong>{lesson.title}</strong><span className={result.score===null?"unmeasured":""}><i style={{width:`${result.score||0}%`}}/>{result.score===null?bi(translated,"Da misurare","Unmeasured"):`${result.score}%`}</span><small>{result.score===null?bi(translated,"Fai una prima prova","Complete a first check"):result.score<70?bi(translated,"Riparazione mirata","Targeted repair"):result.score<85?bi(translated,"Richiamo +7 giorni","Recall after 7 days"):bi(translated,"Mantenimento","Maintenance")}</small></div>})}</div>
  </section>;
}

function CefrTracker({learner,save,translated}:{learner:LearnerState;save:SaveLearner;translated:boolean}){
  const [drafts,setDrafts]=useState<Record<string,string>>({});
  const entryFor=(id:string,state=learner)=>state.cefrEvidence[id]||{status:"not-yet" as const,entries:[]};
  const updateStatus=(id:string,status:"not-yet"|"supported"|"independent")=>save(state=>{const current=entryFor(id,state);return{...state,cefrEvidence:{...state.cefrEvidence,[id]:{...current,status}}}});
  const addEvidence=(id:string)=>{const note=(drafts[id]||"").trim();if(!note)return;save(state=>{const current=entryFor(id,state),entries=[...current.entries,{date:localDateKey(),note}];return{...state,cefrEvidence:{...state.cefrEvidence,[id]:{entries,status:current.status==="not-yet"?"supported":current.status}}}});setDrafts({...drafts,[id]:""})};
  const hasSpacing=(entries:{date:string}[])=>entries.some((entry,index)=>entries.slice(index+1).some(other=>Math.abs(new Date(other.date).getTime()-new Date(entry.date).getTime())>=7*864e5));
  return <section className="cefr-tracker"><div className="cefr-head"><div><p className="eyebrow">PROFILO CEFR · CINQUE CORSIE SEPARATE {translated&&"· FIVE SEPARATE LANES"}</p><h2>{bi(translated,"A1 dimostrato, A2 solo come ponte","Evidence for A1; A2 only as a bridge")}</h2><p>“Indipendente” richiede almeno due prove in giorni separati da una settimana. È un’autovalutazione operativa, non una certificazione.</p>{translated&&<p className="translation-line translation-reveal">Independent requires two pieces of evidence at least a week apart. This is an operational self-audit, not certification.</p>}</div><a href="https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid" target="_blank" rel="noreferrer">{bi(translated,"Griglia ufficiale","Official grid")} ↗</a></div><div className="cefr-lanes">{cefrLanes.map(lane=>{const current=entryFor(lane.id),independentReady=hasSpacing(current.entries);return <article key={lane.id}><header><span>{lane.it}</span>{translated&&<small className="translation-reveal">{lane.en}</small>}<strong>{current.entries.length} {bi(translated,"prove","artifacts")}</strong></header><div className="cefr-target"><small>{bi(translated,"USCITA A1","A1 EXIT")}</small><p>{lane.a1}</p>{translated&&<p className="target-translation translation-reveal" lang="en">{lane.a1En}</p>}<small>{bi(translated,"PONTE A2","A2 BRIDGE")}</small><p>{lane.a2}</p>{translated&&<p className="target-translation translation-reveal" lang="en">{lane.a2En}</p>}</div><div className="evidence-status">{[["not-yet","Non ancora","Not yet"],["supported","Con supporto","Supported"],["independent","Indipendente","Independent"]].map(([id,it,en])=><button key={id} disabled={id==="independent"&&!independentReady} className={current.status===id?"active":""} onClick={()=>updateStatus(lane.id,id as "not-yet"|"supported"|"independent")}>{bi(translated,it,en)}</button>)}</div>{current.entries.slice(-2).map(entry=><div className="evidence-entry" key={`${entry.date}${entry.note}`}><span>{new Date(`${entry.date}T12:00:00`).toLocaleDateString("it-IT",{day:"numeric",month:"short"})}</span><p>{entry.note}</p></div>)}<div className="evidence-add"><input aria-label={`${bi(translated,"Aggiungi una prova per","Add evidence for")} ${lane.it}`} value={drafts[lane.id]||""} onChange={event=>setDrafts({...drafts,[lane.id]:event.target.value})} placeholder={bi(translated,"Es. registrazione hotel 3:10, senza copione","E.g. hotel recording, 3:10, unscripted")}/><button onClick={()=>addEvidence(lane.id)}>+ {bi(translated,"Prova","Evidence")}</button></div>{!independentReady&&current.entries.length>0&&<small className="spacing-note">{bi(translated,"Aggiungi una seconda prova ≥7 giorni dopo per sbloccare “Indipendente”.","Add a second artifact ≥7 days later to unlock Independent.")}</small>}</article>})}</div></section>;
}

function CurriculumCoverage({content,translated}:{content:Content;translated:boolean}){
  const runtime=expandExercises(content).length, sentenceCount=content.reading.reduce((sum,reading)=>sum+reading.sentences.length,0);
  const metrics=[
    {it:"Vocabolario",en:"Vocabulary",value:content.vocab.length,target:350,unit:"parole",unitEn:"words"},
    {it:"Letture graduate",en:"Graded readings",value:content.reading.length,target:20,unit:"testi",unitEn:"texts"},
    {it:"Frasi di lettura",en:"Reading sentences",value:sentenceCount,target:80,unit:"frasi",unitEn:"sentences"},
    {it:"Regole grammaticali",en:"Grammar rules",value:content.grammar_rule.length,target:24,unit:"carte",unitEn:"cards"},
    {it:"Paradigmi verbali",en:"Verb paradigms",value:content.verb.length,target:25,unit:"verbi",unitEn:"verbs"},
    {it:"Combinazioni preposizionali",en:"Preposition combinations",value:content.preposition.length,target:30,unit:"forme",unitEn:"forms"},
    {it:"Esercizi curati",en:"Curated exercises",value:content.exercise.length,target:168,unit:"attività",unitEn:"activities"},
    {it:"Variazioni attive",en:"Active variations",value:runtime,target:900,unit:"prove",unitEn:"attempts"},
  ];
  const ready=metrics.filter(metric=>metric.value>=metric.target).length,percent=Math.round(ready/metrics.length*100);
  return <section className="coverage-audit"><div className="coverage-intro"><div><p className="eyebrow">BIBLIOTECA DEL PERCORSO · 8 SETTIMANE</p><h2>La dispensa digitale è pronta al {percent}%</h2>{translated&&<p className="translation-reveal">The digital practice library meets {ready} of {metrics.length} internal coverage targets.</p>}<small>Questi valori descrivono la quantità di materiale disponibile, non il livello del learner.</small>{translated&&<small className="translation-reveal">These values describe available material, not learner proficiency.</small>}</div><div className="coverage-score" style={{"--p":`${percent}%`} as React.CSSProperties}><strong>{percent}%</strong><span>copertura</span></div></div><div className="coverage-grid">{metrics.map(metric=>{const pct=Math.min(100,Math.round(metric.value/metric.target*100));return <article key={metric.it}><span>{metric.it}{translated&&<small>{metric.en}</small>}</span><strong>{metric.value}</strong><em>/ {metric.target} {translated?metric.unitEn:metric.unit}</em><i><b style={{width:`${pct}%`}}/></i></article>})}</div></section>
}

function LessonPanel({lesson,content,learner,translated,close,start}:{lesson:Lesson;content:Content;learner:LearnerState;translated:boolean;close:()=>void;start:(id:string)=>void}){
  const [tab,setTab]=useState<"overview"|"grammar"|"notes">("overview"),dialogRef=useRef<HTMLElement>(null),rules=lesson.grammarRuleIds.map(id=>content.grammar_rule.find(rule=>rule.id===id)).filter(Boolean) as Content["grammar_rule"], exerciseCount=content.exercise.filter(e=>e.lessonId===lesson.id).length+5+lesson.mistakes.length;
  useEffect(()=>{
    const dialog=dialogRef.current,previousFocus=document.activeElement as HTMLElement|null,previousOverflow=document.body.style.overflow;
    if(!dialog)return;
    const background=[...document.querySelectorAll<HTMLElement>(".app-shell > header, .app-shell > main, .app-shell > footer")],settings=background.map(element=>({element,inert:element.inert,ariaHidden:element.getAttribute("aria-hidden")}));
    background.forEach(element=>{element.inert=true;element.setAttribute("aria-hidden","true")});document.body.style.overflow="hidden";
    window.requestAnimationFrame(()=>dialog.querySelector<HTMLElement>(".modal-close")?.focus());
    const key=(event:KeyboardEvent)=>{if(event.key==="Escape"){event.preventDefault();close();return}if(event.key!=="Tab")return;const controls=[...dialog.querySelectorAll<HTMLElement>('button:not([disabled]), a[href], input:not([disabled]), textarea:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])')].filter(element=>element.getClientRects().length>0);if(!controls.length){event.preventDefault();dialog.focus();return}const first=controls[0],last=controls.at(-1)!;if(event.shiftKey&&(document.activeElement===first||document.activeElement===dialog)){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}else if(!dialog.contains(document.activeElement)){event.preventDefault();first.focus()}};
    document.addEventListener("keydown",key);
    return()=>{document.removeEventListener("keydown",key);document.body.style.overflow=previousOverflow;settings.forEach(({element,inert,ariaHidden})=>{element.inert=inert;if(ariaHidden===null)element.removeAttribute("aria-hidden");else element.setAttribute("aria-hidden",ariaHidden)});if(previousFocus?.isConnected)previousFocus.focus()};
  },[lesson.id]);
  return <div className="modal-backdrop" onMouseDown={close}><article ref={dialogRef} tabIndex={-1} className="modal lesson-hub" role="dialog" aria-modal="true" aria-labelledby={`lesson-title-${lesson.id}`} onMouseDown={e=>e.stopPropagation()}><button className="modal-close" aria-label="Chiudi lezione" onClick={close}>×</button><div className="modal-kicker"><span className={`course-dot c${lesson.course}`}>C{lesson.course}</span>SETTIMANA {lesson.week}{translated&&" · WEEK"}<b>{exerciseCount} esercizi</b></div><h1 id={`lesson-title-${lesson.id}`}>{lesson.title}</h1>{translated&&<p className="modal-subtitle translation-reveal" lang="en">{lesson.subtitle}</p>}<div className="lesson-summary"><span>IN BREVE {translated&&"· AT A GLANCE"}</span><p>{lesson.summaryIt}</p>{translated&&<small className="translation-reveal" lang="en">{lesson.summaryEn}</small>}</div><div className="hub-tabs" role="group" aria-label="Contenuti della lezione"><button aria-pressed={tab==="overview"} className={tab==="overview"?"active":""} onClick={()=>setTab("overview")}>Panoramica</button><button aria-pressed={tab==="grammar"} className={tab==="grammar"?"active":""} onClick={()=>setTab("grammar")}>Grammatica <span>{rules.length}</span></button><button aria-pressed={tab==="notes"} className={tab==="notes"?"active":""} onClick={()=>setTab("notes")}>Quaderno</button></div>
  {tab==="overview"&&<><div className="can-do-panel"><span>SO FARE · A1</span><strong>{lesson.canDoIt}</strong>{translated&&<small className="translation-reveal">{lesson.canDo}</small>}</div><section className="modal-section"><p className="eyebrow">FRASE MODELLO {translated&&"· MODEL SENTENCE"}</p><blockquote>{lesson.italian}</blockquote>{translated?<p className="panel-translation translation-reveal"><span>EN</span>{lesson.english}</p>:<small className="immersion-hint">Traduzione nascosta · attiva Bilingue per controllare</small>}<CopyButton text={lesson.italian}/></section><section className="modal-section"><p className="eyebrow">DA RICORDARE {translated&&"· REMEMBER"}</p><div className="remember-grid">{lesson.remember.map((note,index)=><article key={note.it}><span>0{index+1}</span><strong>{note.it}</strong>{translated&&<small className="translation-reveal">{note.en}</small>}</article>)}</div></section><section className="modal-section"><p className="eyebrow">PADRONANZA PER ABILITÀ {translated&&"· SKILL MASTERY"}</p><div className="modal-skills">{skills.map(skill=>{const item=masteryFor(learner,lesson.id,skill),pct=accuracy(item.attempts,item.correct);return <div key={skill} className={item.attempts?"":"unmeasured"}><span>{skill}</span><i><b style={{width:`${item.attempts?pct:0}%`}}/></i><strong>{item.attempts?`${pct}%`:"—"}</strong></div>})}</div></section></>}
  {tab==="grammar"&&<section className="grammar-stack">{rules.map((rule,index)=><article className="grammar-rule-card" key={rule.id}><div><span>REGOLA {String(index+1).padStart(2,"0")}</span><h2>{rule.titleIt}</h2>{translated&&<small className="translation-reveal">{rule.titleEn}</small>}</div><p>{rule.ruleIt}</p>{translated&&<p className="rule-translation translation-reveal">{rule.ruleEn}</p>}<div className="rule-example"><strong>{rule.examples[0].it}</strong>{translated&&<small className="translation-reveal">{rule.examples[0].en}</small>}</div><div className="rule-exception"><span>ATTENZIONE</span><p>{rule.exceptionIt}</p>{translated&&<small className="translation-reveal">{rule.exceptionEn}</small>}</div></article>)}</section>}
  {tab==="notes"&&<><section className="notebook-section"><p className="eyebrow">SCRIVI SUL QUADERNO {translated&&"· WRITE THIS DOWN"}</p>{lesson.writeDown.map((note,index)=><label key={note.it}><input type="checkbox"/><span><strong>{note.it}</strong>{translated&&<small className="translation-reveal">{note.en}</small>}</span><b>{index+1}</b></label>)}</section><section className="modal-section"><p className="eyebrow">ERRORI TIPICI {translated&&"· COMMON MISTAKES"}</p><div className="mistake-stack">{lesson.mistakes.map(m=><article key={m.wrong}><div><del>{m.wrong}</del><strong>→ {m.right}</strong></div><p>{m.noteIt}</p>{translated&&<small className="translation-reveal">{m.noteEn}</small>}</article>)}</div></section><section className="source-note"><span>BASE DIDATTICA</span><p>{lesson.sourceRefs.join(" · ")}</p></section></>}
  <button className="complete-button" onClick={()=>start(lesson.id)}>Avvia {exerciseCount} esercizi della lezione {translated&&"· Start lesson practice"} →</button></article></div>
}
